<?php $title='Activity & Audit';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1>Activity & Audit</h1><p>Stage-based activity, security access and material change history.</p></div></div><form class="toolbar" method="get" action="<?=route('activities')?>"><input name="q" value="<?=e($q??'')?>" placeholder="Search module, action or user"><select name="stage"><option value="">All stages</option><?php foreach(['stage_1','stage_2','stage_3'] as $st):?><option <?=$stage===$st?'selected':''?>><?=$st?></option><?php endforeach;?></select><button class="secondary">Filter</button></form><div class="panel table-wrap"><table><tr><th>Date</th><th>User</th><th>Module</th><th>Action</th><th>Stage</th><th>Changes</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['user_name'])?></td><td><?=e($r['module_name'])?></td><td><?=e($r['action'])?></td><td><span class="badge"><?=e($r['activity_stage'])?></span></td><td><details><summary>View</summary><pre><?=e(json_encode(['before'=>json_decode($r['old_value']??'null',true),'after'=>json_decode($r['new_value']??'null',true)],JSON_PRETTY_PRINT))?></pre></details></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../layouts/footer.php';?>
